CREATE TABLE "conversations" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "conversations_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"type" varchar NOT NULL,
	"title" varchar(120),
	"created_by" bigint,
	"direct_user_low_id" bigint,
	"direct_user_high_id" bigint,
	"last_seq" bigint DEFAULT 0 NOT NULL,
	"activity_version" bigint DEFAULT 0 NOT NULL,
	"last_message_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chk_conversations_type" CHECK ("conversations"."type" IN ('DIRECT', 'GROUP')),
	CONSTRAINT "chk_conversations_title" CHECK (("conversations"."type" = 'GROUP' AND "conversations"."title" IS NOT NULL AND char_length(btrim("conversations"."title")) BETWEEN 1 AND 120) OR ("conversations"."type" = 'DIRECT' AND "conversations"."title" IS NULL)),
	CONSTRAINT "chk_conversations_direct_cols" CHECK (("conversations"."type" = 'DIRECT' AND "conversations"."direct_user_low_id" IS NOT NULL AND "conversations"."direct_user_high_id" IS NOT NULL AND "conversations"."direct_user_low_id" < "conversations"."direct_user_high_id") OR ("conversations"."type" = 'GROUP' AND "conversations"."direct_user_low_id" IS NULL AND "conversations"."direct_user_high_id" IS NULL))
);
